      .image-card {
        overflow: hidden;
      }

      .image-frame {
        padding: clamp(0.75rem, 2vw, 1.25rem);
        background: linear-gradient(180deg, #ffffff, var(--surface-muted));
      }

      .preview-image {
        display: block;
        width: 100%;
        max-width: 100%;
        height: auto;
        border-radius: 1.35rem;
        box-shadow: 0 18px 44px #1720331f;
      }

      .image-meta {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        align-items: center;
        justify-content: space-between;
        padding: 1rem clamp(1rem, 3vw, 1.5rem) 1.25rem;
