        max-width: 33rem;
        margin: 1.1rem 0 0;
        color: var(--muted);
        font-size: clamp(1rem, 2vw, 1.15rem);
        line-height: 1.65;
      }

      .details-card {
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .stat-list {
        display: grid;
        gap: 0.85rem;
        margin: 1.6rem 0;
        padding: 0;
        list-style: none;
      }

      .stat-list li {
        display: flex;
        flex-wrap: wrap;
        gap: 0.35rem 0.75rem;
        justify-content: space-between;
        min-width: 0;
        padding: 0.9rem 1rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: #f8fafc;
        overflow-wrap: anywhere;
