        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        align-items: center;
      }

      button,
      .button-link {
        min-height: 2.75rem;
        padding: 0.75rem 1rem;
        border: 1px solid transparent;
        border-radius: 999px;
        font: inherit;
        font-weight: 800;
        line-height: 1;
        text-decoration: none;
        cursor: pointer;
      }

      button:focus-visible,
      .button-link:focus-visible,
      .skip-link:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .button-primary,
      .button-link {
        background: var(--accent);
        color: #ffffff;
      }

      .button-primary:hover,
      .button-link:hover {
        background: var(--accent-strong);
      }

      .button-secondary {
        border-color: var(--border);
        background: var(--surface);
        color: var(--text);
      }

      .button-secondary:hover {
        background: var(--surface-muted);
      }

      .button-danger {
        background: var(--danger);
        color: #ffffff;
      }

      .button-danger:hover {
        background: var(--danger-strong);
      }

      .trigger {
        border-color: #f0b7b2;
        background: #fff1f0;
        color: var(--danger);
      }

      .trigger:hover {
        background: #ffe2df;
      }

      .supporting-note {
        margin: 0.85rem 0 0;
        color: var(--muted);
        font-size: 0.95rem;
        line-height: 1.55;
      }

      dialog {
        width: min(92vw, 30rem);
        padding: 0;
        border: 1px solid var(--border);
        border-radius: 1.6rem;
        background: var(--surface);
        color: var(--text);
        box-shadow: 0 34px 90px #0f172a42;
      }

      dialog::backdrop {
        background: #0f172abf;
      }

      .dialog-content {
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        margin-bottom: 1rem;
        place-items: center;
        border-radius: 1rem;
        background: #fff1f0;
        color: var(--danger);
      }

      .dialog-icon svg {
        width: 1.45rem;
        height: 1.45rem;
      }

      .dialog-title {
        margin: 0;
        font-size: clamp(1.45rem, 5vw, 2rem);
        line-height: 1.1;
        letter-spacing: -0.04em;
      }

      .dialog-description {
        margin: 0.75rem 0 1.5rem;
        color: var(--muted);
        line-height: 1.6;
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
