  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const image = {
        title: "Sunset Ridge",
        fileName: "sunset-ridge.jpg",
        dimensions: "2400 x 1600",
        collection: "Travel favorites",
        updated: "Updated today",
        alt: "A warm sunset over layered mountain ridges with a soft orange sky.",
        src:
          "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1200 800'%3E%3Cdefs%3E%3ClinearGradient id='sky' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop offset='0' stop-color='%23f8b878'/%3E%3Cstop offset='.55' stop-color='%238fb7d8'/%3E%3Cstop offset='1' stop-color='%232f5873'/%3E%3C/linearGradient%3E%3ClinearGradient id='sun' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23fff2a6'/%3E%3Cstop offset='1' stop-color='%23ff8d4a'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1200' height='800' fill='url(%23sky)'/%3E%3Ccircle cx='880' cy='250' r='90' fill='url(%23sun)'/%3E%3Cpath d='M0 500 220 340 370 455 520 300 710 480 880 330 1200 540v260H0z' fill='%231c3348'/%3E%3Cpath d='M0 580 170 460 360 590 560 420 760 610 960 470 1200 640v160H0z' fill='%23264f67'/%3E%3Cpath d='M0 680c180-80 330-83 520-18 200 69 430 42 680-70v208H0z' fill='%23f7efe3' fill-opacity='.72'/%3E%3C/svg%3E"
      };

      function Header() {
        return `
          <header class="site-header">
            <div class="brand" aria-label="Luma Library">
              <span class="brand-mark" aria-hidden="true">L</span>
              <span>Luma Library</span>
            </div>
          </header>
        `;
      }

      function ImagePreviewCard() {
        return `
          <section class="image-card" aria-labelledby="image-title">
            <div class="image-frame">
              <img class="preview-image" src="${image.src}" alt="${image.alt}">
            </div>
            <div class="image-meta">
              <div>
                <p class="eyebrow">Image preview</p>
                <h2 id="image-title">${image.title}</h2>
              </div>
              <button class="trigger" type="button" data-open-dialog>
                Delete image
              </button>
            </div>
          </section>
        `;
      }

      function DetailsPanel() {
        return `
          <section class="details-card" aria-labelledby="page-title">
            <p class="eyebrow">Library asset</p>
            <h1 id="page-title">${image.title}</h1>
            <p class="lede">
              Preview the selected image and manage its library status. Deleting removes this image from your saved collection.
            </p>
            <ul class="stat-list" aria-label="Image details">
              <li><span class="stat-label">File</span><span class="stat-value">${image.fileName}</span></li>
              <li><span class="stat-label">Size</span><span class="stat-value">${image.dimensions}</span></li>
              <li><span class="stat-label">Collection</span><span class="stat-value">${image.collection}</span></li>
            </ul>
            <div class="button-row">
              <a class="button-link" href="#image-title">View image</a>
              <button class="button-secondary" type="button">Download</button>
            </div>
            <p class="supporting-note">${image.updated}</p>
            <p id="status-message" class="sr-only" aria-live="polite"></p>
          </section>
        `;
      }

      function DeleteDialog() {
        return `
          <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
            <div class="dialog-content">
              <div class="dialog-icon" aria-hidden="true">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                  <path d="M3 6h18"></path>
                  <path d="M8 6V4h8v2"></path>
                  <path d="M19 6l-1 14H6L5 6"></path>
                  <path d="M10 11v5"></path>
                  <path d="M14 11v5"></path>
                </svg>
              </div>
              <h2 id="dialog-title" class="dialog-title">Delete this image?</h2>
              <p id="dialog-description" class="dialog-description">
                This will remove "${image.title}" from your library. You can upload it again later, but this saved item will be deleted.
              </p>
              <div class="button-row">
                <button class="button-danger" type="button" data-confirm-delete>
                  Delete image
                </button>
                <button class="button-secondary" type="button" data-close-dialog>
                  Keep image
                </button>
              </div>
            </div>
          </dialog>
        `;
      }

      function App() {
        return `
          ${Header()}
          <main id="main-content">
            <div class="preview-shell">
              ${DetailsPanel()}
              ${ImagePreviewCard()}
            </div>
          </main>
          ${DeleteDialog()}
        `;
      }

      const root = document.querySelector("#app");
      root.innerHTML = App();

      const dialog = document.querySelector("#delete-dialog");
      const openButton = document.querySelector("[data-open-dialog]");
      const closeButton = document.querySelector("[data-close-dialog]");
      const confirmButton = document.querySelector("[data-confirm-delete]");
      const statusMessage = document.querySelector("#status-message");
      let lastFocusedElement = null;

      function openDialog() {
        lastFocusedElement = document.activeElement;
        dialog.showModal();
        document.body.classList.add("modal-open");
        closeButton.focus();
      }

      function closeDialog() {
        dialog.close();
      }

      openButton.addEventListener("click", openDialog);
      closeButton.addEventListener("click", closeDialog);

      confirmButton.addEventListener("click", () => {
        statusMessage.textContent = `${image.title} was deleted from your library.`;
        dialog.close("deleted");
      });

      dialog.addEventListener("close", () => {
        document.body.classList.remove("modal-open");

        if (lastFocusedElement && typeof lastFocusedElement.focus === "function") {
          lastFocusedElement.focus();
        }
      });
    </script>
  </body>
</html>
