               </button>
             </div>
           </section>
         `;
       }

       function DetailsPanel() {
         return `
           <section class="details-card" aria-labelledby="page-title">
             <p class="eyebrow">Library asset</p>
             <h1 id="page-title">${image.title}</h1>
             <p class="lede">
