           </main>
           ${DeleteDialog()}
         `;
       }

       const root = document.querySelector("#app");
       root.innerHTML = App();

       const dialog = document.querySelector("#delete-dialog");
       const openButton = document.querySelector("[data-open-dialog]");
       const closeButton = document.querySelector("[data-close-dialog]");
       const confirmButton = document.querySelector("[data-confirm-delete]");
       const statusMessage = document.querySelector("#status-message");
       let lastFocusedElement = null;

       function openDialog() {
         lastFocusedElement = document.activeElement;
         dialog.showModal();
         document.body.classList.add("modal-open");
         closeButton.focus();
       }

       function closeDialog() {
         dialog.close();
       }

       openButton.addEventListener("click", openDialog);
       closeButton.addEventListener("click", closeDialog);

       confirmButton.addEventListener("click", () => {
         statusMessage.textContent = `${image.title} was deleted from your library.`;
